The above should work, but this was a small oversight i the rpg_core.js/rmmz_core.js, and can easily be fixed with the below code as a plugin ^^
Both solutions are valid,
@caethyril
's solution is ESPECIALLY good to use if you intend to keep all your games assets from blurring( i.e. characters, windows, pictures, if for some reason they use a float value.., etc ).
JavaScript:
Bitmap.prototype.drawText = function(text, x, y, maxWidth, lineHeight, align) {
    // [Note] Different browser makes different rendering with
    //   textBaseline == 'top'. So we use 'alphabetic' here.
    const context = this.context;
    const alpha = context.globalAlpha;
    maxWidth = maxWidth || 0xffffffff;
    let tx = x;
    let ty = Math.round(y + lineHeight / 2 + this.fontSize * 0.35);
    if (align === "center") {
//===================================================================//
// The line below is how it CURRENTLY is done...
//===================================================================//
        // tx += maxWidth / 2;
//===================================================================//
// THIS is what it should be to prevent blurring in certain circumstances.
//===================================================================//
        tx += Math.round( maxWidth / 2 );
    }
    if (align === "right") {
        tx += maxWidth;
    }
    context.save();
    context.font = this._makeFontNameText();
    context.textAlign = align;
    context.textBaseline = "alphabetic";
    context.globalAlpha = 1;
    this._drawTextOutline(text, tx, ty, maxWidth);
    context.globalAlpha = alpha;
    this._drawTextBody(text, tx, ty, maxWidth);
    context.restore();
    this._baseTexture.update();
};
